import java.io.File;
import java.io.IOException;

public class ImportingUtilities {

    // other methods

    /**
     * Allocates a unique file within the specified directory, ensuring that the
     * filename does not contain path traversal sequences and that the resulting
     * file resides strictly within {@code dir}. If a file with the same name
     * already exists, a numeric suffix is appended to create a unique name.
     *
     * @param dir  the target directory where the file should be created
     * @param name the desired filename (may contain query parameters)
     * @return a {@link File} object representing the allocated file
     * @throws IOException if the filename cannot be sanitized or the file cannot
     *                     be created
     */
    static public File allocateFile(File dir, String name) throws IOException {
        // Strip query parameters
        int q = name.indexOf('?');
        if (q > 0) {
            name = name.substring(0, q);
        }

        // Reject absolute paths or paths containing separators
        if (name.contains("/") || name.contains("\\") || name.startsWith(".")) {
            throw new IOException("Invalid filename: " + name);
        }

        // Ensure the directory exists
        if (!dir.isDirectory()) {
            throw new IOException("Target is not a directory: " + dir);
        }

        // Resolve canonical path to guard against symlink attacks
        File baseDir = dir.getCanonicalFile();

        // Construct initial file
        File file = new File(baseDir, name);

        // Verify that the file is within the intended directory
        if (!isWithinBase(file, baseDir)) {
            throw new IOException("Filename resolves outside the target directory: " + name);
        }

        // Determine prefix and suffix for unique naming
        int dot = name.lastIndexOf('.');
        String prefix = dot < 0 ? name : name.substring(0, dot);
        String suffix = dot < 0 ? "" : name.substring(dot);
        int index = 2;

        // Append numeric suffix until a unique filename is found
        while (file.exists()) {
            file = new File(baseDir, prefix + "-" + index++ + suffix);
            if (!isWithinBase(file, baseDir)) {
                throw new IOException("Generated filename resolves outside the target directory");
            }
        }

        // Create parent directories if necessary
        File parent = file.getParentFile();
        if (parent != null && !parent.mkdirs() && !parent.isDirectory()) {
            throw new IOException("Failed to create parent directories for: " + file);
        }

        return file;
    }

    /**
     * Checks whether {@code child} is located within {@code base}.
     *
     * @param child the file to check
     * @param base  the base directory
     * @return true if {@code child} is within {@code base}, false otherwise
     * @throws IOException if canonical paths cannot be resolved
     */
    private static boolean isWithinBase(File child, File base) throws IOException {
        String childPath = child.getCanonicalPath();
        String basePath = base.getCanonicalPath();
        return childPath.startsWith(basePath + File.separator);
    }

    // other methods

}
