import org.codehaus.plexus.components.io.attributes.SymlinkUtils;
import org.codehaus.plexus.logging.AbstractLogEnabled;
import org.codehaus.plexus.util.FileUtils;
import org.codehaus.plexus.util.IOUtil;
import org.codehaus.plexus.util.StringUtils;

public abstract class AbstractUnArchiver extends AbstractLogEnabled implements UnArchiver, FinalizerEnabled {

    private boolean overwrite = true;
    private boolean ignorePermissions = false;

    // other methods

    protected void extractFile(final File srcF, final File dir, final InputStream compressedInputStream,
                               final String entryName, final Date entryDate, final boolean isDirectory,
                               final Integer mode, String symlinkDestination) throws IOException, ArchiverException {

        // Resolve the target file path
        final File f = FileUtils.resolveFile(dir, entryName);

        // Validate that the resolved file is within the intended extraction directory
        final String canonicalDirPath = dir.getCanonicalPath();
        final String canonicalTargetPath = f.getCanonicalPath();

        if (!canonicalTargetPath.startsWith(canonicalDirPath + File.separator)) {
            throw new ArchiverException("Entry '" + entryName + "' resolves to a location outside the extraction directory.");
        }

        try {
            // Skip extraction if overwrite is disabled and the file already exists with newer or equal timestamp
            if (!isOverwrite() && f.exists() && (f.lastModified() >= entryDate.getTime())) {
                return;
            }

            // Ensure parent directories exist
            final File dirF = f.getParentFile();
            if (dirF != null) {
                dirF.mkdirs();
            }

            // Handle symbolic links separately
            if (!StringUtils.isEmpty(symlinkDestination)) {
                SymlinkUtils.createSymbolicLink(f, new File(symlinkDestination));
            } else if (isDirectory) {
                f.mkdirs();
            } else {
                // Extract regular file
                OutputStream out = null;
                try {
                    out = new FileOutputStream(f);
                    IOUtil.copy(compressedInputStream, out);
                } finally {
                    IOUtil.close(out);
                }
            }

            // Set last modified timestamp
            f.setLastModified(entryDate.getTime());

            // Apply permissions if not ignored
            if (!isIgnorePermissions() && mode != null && !isDirectory) {
                ArchiveEntryUtils.chmod(f, mode);
            }
        } catch (final FileNotFoundException ex) {
            getLogger().warn("Unable to expand to file " + f.getPath(), ex);
        }
    }

    // other methods

    @Override
    public boolean isIgnorePermissions() {
        return ignorePermissions;
    }

    @Override
    public boolean isOverwrite() {
        return overwrite;
    }

}
