     * Decompresses data from the given {@link InputStream} into the provided output buffer.
     *
     * <p>This method implements a simple run-length decoding algorithm used for RGBE image
     * decompression. It has been hardened against malformed input that could cause
     * infinite loops or excessive memory usage.</p>
     *
     * @param in  the input stream containing compressed data
     * @param out the output buffer to receive decompressed bytes
     * @throws IOException if an I/O error occurs or if the input data is malformed
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        int position = 0;
        final int total = out.length;

        while (position < total) {
            final int n = in.read();
            if (n == -1) {
                throw new IOException("Unexpected end of stream while decompressing");
            }

            if (n > 128) {
                final int value = in.read();
                if (value == -1) {
                    throw new IOException("Unexpected end of stream while decompressing");
                }
                final int count = n & 0x7F;
                if (count == 0) {
                    throw new IOException("Invalid run length (zero) encountered during decompression");
                }
                if (position + count > total) {
                    throw new IOException("Decompressed data exceeds expected output size");
                }
                final byte b = (byte) value;
                for (int i = 0; i < count; i++) {
                    out[position++] = b;
                }
            } else {
                final int count = n;
                if (count == 0) {
                    throw new IOException("Invalid literal length (zero) encountered during decompression");
                }
                if (position + count > total) {
                    throw new IOException("Decompressed data exceeds expected output size");
                }
                for (int i = 0; i < count; i++) {
                    final int val = in.read();
                    if (val == -1) {
                        throw new IOException("Unexpected end of stream while decompressing");
                    }
                    out[position++] = (byte) val;
                }
            }
        }
    }

