     * Extends the value {@code v} to the nearest multiple of {@code vt},
     * where {@code vt} is calculated as {@code 1 << (t - 1)}.
     *
     * @param v the initial value to extend
     * @param t the exponent used to calculate the step size; must be >= 1
     * @return the extended value
     * @throws IllegalArgumentException if {@code t <= 0} or if the calculation would overflow
     */
    private int extend(int v, final int t) {
        if (t <= 0) {
            throw new IllegalArgumentException("Parameter 't' must be greater than 0");
        }

        // Calculate vt once; ensure no overflow occurs
        if (t >= 31) { // 1 << 30 is the largest positive shift for int
            throw new IllegalArgumentException("Parameter 't' too large, would cause overflow");
        }
        final int vt = 1 << (t - 1);

        // If v is already >= vt, no extension needed
        if (v >= vt) {
            return v;
        }

        // Compute the difference needed to reach the next multiple of vt
        final int diff = vt - v;

        // Ensure that adding diff does not overflow
        if (diff > Integer.MAX_VALUE - v) {
            throw new IllegalArgumentException("Extension would cause integer overflow");
        }

        return v + diff;
    }

