    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // Read the request body safely
        String requestBody = IOUtils.toString(request.getReader());
        ScimUser scimUserFromRequest = JsonUtils.readValue(requestBody, ScimUser.class);

        // Extract the user ID from the URL path
        String id = UaaUrlUtils.extractPathVariableFromUrl(USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // Get the current zone ID
        String zoneId = IdentityZoneHolder.get().getId();

        ScimUser scimUserFromDb;
        try {
            scimUserFromDb = scimUserProvisioning.retrieve(id, zoneId);
        } catch (ScimResourceNotFoundException e) {
            // If the user does not exist, allow the operation (e.g., creation)
            return true;
        }

        // Verify that the authenticated user is the same as the user being updated
        // The authenticated user's ID is stored in the request attribute "uaa.user.id"
        Object authUserIdObj = request.getAttribute("uaa.user.id");
        if (authUserIdObj == null || !id.equals(authUserIdObj.toString())) {
            return false;
        }

        // Ensure that the primary email is unchanged unless verified
        if (!scimUserFromDb.getPrimaryEmail().equals(scimUserFromRequest.getPrimaryEmail())) {
            // Allow email change only if the new email is verified
            if (!scimUserFromRequest.isVerified()) {
                return false;
            }
        }

        // Ensure that the username is unchanged
        if (!scimUserFromDb.getUserName().equals(scimUserFromRequest.getUserName())) {
            return false;
        }

        // Ensure that the verified flag is unchanged
        if (scimUserFromDb.isVerified() != scimUserFromRequest.isVerified()) {
            return false;
        }

        // Ensure that the active flag is unchanged
        if (scimUserFromDb.isActive() != scimUserFromRequest.isActive()) {
            return false;
        }

        // Ensure that the origin is unchanged
        if (!scimUserFromDb.getOrigin().equals(scimUserFromRequest.getOrigin())) {
            return false;
        }

        return true;
    }

